import{_ as t,o as a,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const m=JSON.parse('{"title":"Agent 面试 · 对比与选型口述","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/compare-interview.md","filePath":"guide/agent/compare-interview.md"}'),l={name:"guide/agent/compare-interview.md"};function d(n,e,o,s,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-面试-·-对比与选型口述" tabindex="-1">Agent 面试 · 对比与选型口述 <a class="header-anchor" href="#agent-面试-·-对比与选型口述" aria-label="Permalink to “Agent 面试 · 对比与选型口述”">​</a></h1><blockquote><p>面试官问「你们为什么用 XX / 不用 YY」时用。厂商表见 <a href="/my-vitepress-site/ai/dev/basics/agent-landscape.html">主流 Agent 厂商一览</a>。</p></blockquote><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>Cursor / Claude Code / Copilot 怎么选？</li><li>为什么不直接上「全自动 Devin 类」？</li><li>自研 Agent 框架还是用现成产品？</li><li>国内 CodeBuddy / 通义灵码和国外差在哪？（开放谈）</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="ide-结对-vs-终端-agent-vs-云端委托" tabindex="-1">IDE 结对 vs 终端 Agent vs 云端委托 <a class="header-anchor" href="#ide-结对-vs-终端-agent-vs-云端委托" aria-label="Permalink to “IDE 结对 vs 终端 Agent vs 云端委托”">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>代表</th><th>适合</th><th>面试怎么说</th></tr></thead><tbody><tr><td>AI IDE</td><td>Cursor、Copilot</td><td>日常改代码、可控</td><td>人在环，节奏快</td></tr><tr><td>终端 Agent</td><td>Claude Code、Codex CLI</td><td>多文件、长任务</td><td>权限与 diff 要审</td></tr><tr><td>云端委托</td><td>Devin、部分 Cloud Agent</td><td>异步出 PR</td><td>范围要写清，适合明确票</td></tr></tbody></table><p>金句：<strong>日常提效用 IDE；深改用终端；异步票才考虑强委托。</strong></p><h3 id="自研-vs-产品" tabindex="-1">自研 vs 产品 <a class="header-anchor" href="#自研-vs-产品" aria-label="Permalink to “自研 vs 产品”">​</a></h3><ul><li>业务要接内部 OA/ERP、强权限审计 → 自研编排 + 官方模型 API 更常见。</li><li>纯研发提效 → 直接产品（Cursor 等），别重复造 IDE。</li><li>自研价值在：<strong>工具契约、状态机、与领域系统集成</strong>，不在再做一个聊天窗。</li></ul><h3 id="为何不一步「全自动」" tabindex="-1">为何不一步「全自动」 <a class="header-anchor" href="#为何不一步「全自动」" aria-label="Permalink to “为何不一步「全自动」”">​</a></h3><ul><li>范围不清时全自动 = 大规模误改。</li><li>先人审 diff / 先确认表单，再扩大自主。</li><li>体现你有工程判断，不是追概念。</li></ul><h3 id="国内产品" tabindex="-1">国内产品 <a class="header-anchor" href="#国内产品" aria-label="Permalink to “国内产品”">​</a></h3><ul><li>数据合规、内网、腾讯/阿里云生态 → 国内助手有场景。</li><li>能力与生态仍快速变化；选型讲 <strong>场景与约束</strong>，不讲粉圈。</li></ul><hr><h2 id="和「我怎么选模型」的分工" tabindex="-1">和「我怎么选模型」的分工 <a class="header-anchor" href="#和「我怎么选模型」的分工" aria-label="Permalink to “和「我怎么选模型」的分工”">​</a></h2><ul><li>选 <strong>模型底座</strong> → <a href="/my-vitepress-site/ai/dev/basics/how-i-choose-models.html">我怎么选模型</a></li><li>选 <strong>Agent 产品形态</strong> → 本页</li><li>两者别混：同一底座可以嵌在不同产品里，体验差很大。</li></ul>',19)])])}const b=t(l,[["render",d]]);export{m as __pageData,b as default};
